import { replacer, checkedResultOutliers } from '@mdatools-apps/shared/utils';

/**
 * Creates CSV file with PCA result outcomes and download it as a file.
 *
 * @param {Object} res - object with PCA results.
 * @param {Object} dataset - object with dataset used to get the results.
 * @param {string} name - name of the results (e.g. 'cal')
 * @param {Object} model - object with PCA model.
 */
export function downloadResults(res, dataset, name, model) {

   // the excluded rows are taken from the result and not from the caller. the result was computed
   // with one particular list and every block of numbers below is laid out accordingly, so a list
   // handed in on the side can disagree with the data it is applied to. it did: the pv results
   // are computed from a set the outliers are already out of, and passing them again subtracted
   // them a second time and shifted every block of the file
   // an entry that names no real row is silent: it matches no whole 'i' below, so a row the
   // result has no values for is emitted and the file is written misaligned. see
   // 'checkedResultOutliers' for what is refused and why none of it is caught further down
   const outliers = checkedResultOutliers(res.outliers, dataset.values.nrows);

   // number of rows with/without outliers. 'n' is the stride of every block of 'res.v', so it has
   // to be what the result actually holds. if that disagrees with the dataset the file would come
   // out silently misaligned, which is worse than not producing it at all
   const nAll = dataset.values.nrows;
   const nOut = outliers.length;
   const n = res.nrows;

   if (nAll - nOut !== n) {
      throw new Error(
         'Results do not match the dataset: ' + nAll + ' rows minus ' + nOut +
         ' excluded is not ' + n + '.'
      );
   }

   const nComp = res.ncomp;

   // number of empty columns to add in addition to row name and first value
   const nStat = model ? 5 : 4;
   const nfiller = Math.max(nComp, nStat);
   const filler = Array(nfiller).fill('');
   const fillerComp = nComp < nStat ? Array(nStat - nComp).fill('') : [];
   const fillerStat = nStat < nComp ? Array(nComp - nStat).fill('') : [];

   // vector with component names/labels and values separator
   const compNames = Array(nComp).fill(0).map((v, i) => 'PC' + (i + 1));
   const sep = dataset.sep
   const dec = dataset.dec;

   // every value is converted on its own. the exporter used to run one replace over the finished
   // document instead, which rewrote every dot in it: an object label 'sample.1' was exported as
   // 'sample,1', while the file name and the title were added after the replace and kept theirs,
   // so the file mixed the two spellings. only a number is converted here; a string - a label, a
   // heading or the dash of an excluded row - keeps whatever it contains
   const num2str = v => typeof v === 'number' ? String(v).replace('.', dec) : v;
   const row = values => values.map(num2str).join(sep) + '\n';

   // function for adding component based outcomes for every row
   function addChunk(name, offset, rowlabels) {
      out += '\n';
      out += [name + ':', '', '', ...filler].join(sep) + '\n';
      out += ['object', 'group', 'outlier', ...compNames, ...fillerComp].join(sep) + '\n';

      // array with current outcome (score, etc) n rows x nComp columns
      const values = res.v.subarray(offset, offset + nComp * n);

      // n - is number of rows in result objects without outliers
      // j - is an iterator along these rows
      // nAll - is a number of rows in original dataset
      // i - is an interator along these rows
      let j = 0;
      for (let i = 0; i < nAll; i++) {
         const groupname = dataset.classes ? dataset.classes[i] : '';

         // outlier
         if (nOut > 0 && outliers.includes(i)) {
            out += row([rowlabels[i], groupname, 'yes', ...Array(nComp).fill('-'), ...fillerComp]);
            continue;
         }

         // regular
         const valuesi = Array(nComp);
         for (let a = 0; a < nComp; a++) {
            valuesi[a] = values[a * n + j];
         }

         out += row([rowlabels[i], groupname, '', ...valuesi, ...fillerComp]);
         j = j + 1;
      }
      out += '\n';
   }


   // general information
   let out = '';
   out += row(['Number of components:', nComp, '', ...filler]);
   out += row(['Center:', res.center, '', ...filler]);
   out += row(['Scale:', res.scale, '', ...filler]);

   // statistics
   out += '\n';
   out += ['Statistics:', '', '', ...filler].join(sep) + '\n';
   if (model) {
      // if model is provided we also show eigenvalues
      // but for the sake of simplicity we get the from "res" object
      out += ['', '', 'PC', 'Expvar', 'Cumexpvar', 'Resvar', 'Cumresvar', 'Eigenvalues', ...fillerStat].join(sep) + '\n';
      for (let a = 0; a < nComp; a++) {
         out += row([
            '', '',
            a + 1,
            res.stat.expvar[a],
            res.stat.cumexpvar[a],
            res.stat.resvar[a],
            res.stat.cumresvar[a],
            res.eigenvals[a],
            ...fillerStat
         ]);
      }
   } else {
      out += ['', '', 'PC', 'Expvar', 'Cumexpvar', 'Resvar', 'Cumresvar', ...fillerStat].join(sep) + '\n';
      for (let a = 0; a < nComp; a++) {
         out += row([
            '', '',
            a + 1,
            res.stat.expvar[a],
            res.stat.cumexpvar[a],
            res.stat.resvar[a],
            res.stat.cumresvar[a],
            ...fillerStat
         ]);
      }
   }
   out += '\n';

   // if model is provided show loadings as well
   if (model) {

      // the model is fitted to the preprocessed data and 'model.v' is laid out with its width,
      // which a trim step makes narrower than the raw dataset. taking the number of columns from
      // the dataset here would start every block below at the wrong offset and pair the numbers
      // with labels of variables the model never saw
      const nModelCols = model.ncols;

      out += '\n';
      out += ['Loading, center and scale values:', '', '', ...filler].join(sep) + '\n';
      out += ['variable', 'center', 'scale', ...compNames, ...fillerComp].join(sep) + '\n';
      const center = model.v.subarray(2, 2 + nModelCols);
      const scale = model.v.subarray(2 + nModelCols, 2 + nModelCols * 2);
      const loadings = model.v.subarray(2 + nModelCols * 2, 2 + nModelCols * 2 + nComp * nModelCols);

      for (let i = 0; i < nModelCols; i++) {
         const loadingsi = Array(nComp);

         for (let a = 0; a < nComp; a++) {
            loadingsi[a] = loadings[a * nModelCols + i];
         }
         out += row([model.varlabels[i], center[i], scale[i], ...loadingsi, ...fillerComp]);
      }
      out += '\n';
   }

   // scores and distances
   addChunk('Scores', 0, dataset.objlabels);
   addChunk('Score distances, h', nComp * n, dataset.objlabels);
   addChunk('Orthogonal distances, q', nComp * n * 2, dataset.objlabels);


   // add header
   out = ['Data filename:', dataset.fileName, '', ...filler].join(sep) + '\n' + out;
   let hdr = ['PCA results (' + name + ')', 'https://mda.tools/pca/', '', ...filler].join(sep) + '\n\n';

   // create Blob and start download process
   const blob = new Blob([hdr + out], { type: 'text/csv' });
   const url = window.URL.createObjectURL(blob)
   const a = document.createElement('a')
   a.setAttribute('href', url)
   a.setAttribute('download', `pca-results-${name}.csv`);
   a.click()
   URL.revokeObjectURL(url)
}


/**
 * Creates JSON with model object, stringify it and download as a file.
 *
 * @param {Object} model - object with PCA model
 */
export function downloadModel(model, prepmodel) {
   const modelWithPrep = {...model, prep: prepmodel};
   const blob = new Blob([JSON.stringify(modelWithPrep, replacer)], { type: 'application/json' });
   const url = window.URL.createObjectURL(blob)
   const a = document.createElement('a')
   a.setAttribute('href', url)
   a.setAttribute('download', 'pca-model.json');
   a.click()
   URL.revokeObjectURL(url)
}
