<script>
   /*************************************************************/
   /* Root component for the application                        */
   /*************************************************************/

   import { date2str } from '@mdatools-apps/shared/utils';
   import { checkPrepField, checkPrepChain } from '@mdatools-apps/shared/methods/prep.js';

   import TrainAppContainer from './tab_train/AppContainer.svelte';
   import PredictAppContainer from './tab_new/AppContainer.svelte';
   import App from '@mdatools-apps/shared/components/MainApp.svelte';
   import WASM from '@mdatools-apps/wasm/pca_wasm.js';

   /* callback for resetting the app via session */
   function resetSession(s) {
      s.train.calset = null;
      s.new.model = null;
      s.tab = 0;
   }

   /* callback to check validity of JSON with session */
   function checkSession(s) {
      const keys1 = Object.keys(s);
      if (!['date', 'tab', 'train', 'new'].every(v => keys1.includes(v))) return false;

      const keys2 = Object.keys(s.train);
      if (!['model', 'calset', 'calsetp', 'pvset', 'calres', 'pvres',  'outliers', 'prepType',
         'prepmodel', 'prepmeta', 'prepobj'].every(v => keys2.includes(v))) return false;
      const keys3 = Object.keys(s.new);
      if (!['model', 'newset', 'newres',  'outliers'].every(v => keys3.includes(v))) return false;

      // a session of pls, pls1da, ddsimca or gls has these keys too, and a part 'test' pca never
      // has; their models and results, read as pca ones, throw. an empty one is 0 or null
      if (keys1.includes('test')) return false;
      const is = (v, cls) => !v || (Array.isArray(v.class) && v.class[0] === cls);
      if (![s.train.model, s.new.model].every(v => is(v, 'pcamodel'))) return false;
      if (![s.train.calres, s.train.pvres, s.new.newres].every(v => is(v, 'pcares'))) return false;

      // a stored preprocessing model is rendered as soon as its tab mounts, and the chain read by
      // the creator, where no catch reaches: the checks a file passes (prep's 'checkSession' runs
      // the same); 0 and null are none
      try {
         checkPrepChain(s.train.prepobj);
         for (const p of [s.train.prepmodel, s.new.model?.prep]) checkPrepField(p);
      } catch { return false; }

      return true;
   }

   /* callback to initialize new session */
   function initSession() {
      return {
         date: date2str(new Date()),
         tab: 0,
         train: {
            model : 0,
            calset: 0,
            calsetp: 0,
            pvset: 0,
            calres: 0,
            pvres: 0,
            outliers: [],
            prepType: null,
            prepmodel: 0,
            prepmeta: 0,
            prepobj: [],
         },
         new: {
            model : 0,
            newset: 0,
            newres: 0,
            outliers: []
         }
      }
   }

   // app containers
   const tabs = [
      {name: 'Train', label: 'train', component: TrainAppContainer},
      {name: 'Project', label: 'new', component: PredictAppContainer},
   ]
</script>

<App
   appID="pca"
   appTitle="PCA"
   appShortTitle="PCA"
   appSlogan="Principal component analysis"
   {WASM}
   {tabs}
   {initSession}
   {checkSession}
   {resetSession}
>

   {#snippet footer()}
      <p>Current release: <span>2.6.2</span>
      Feedback: <a class="paper-link" href="mailto:help@mda.tools?subject=PCA app">help@mda.tools</a>
      Tutorial: <a class="paper-link" href="/pca/Wines.zip" download>dataset</a>
      | <a href="https://www.youtube.com/playlist?list=PLep7KM9cEyFmpfjgu7n4y-slf8AAN74xC">video lessons</a>
      </p>
   {/snippet}

   {#snippet info()}
   <h2>Principal Component Analysis</h2>
   <p>Authors: <em>Sergey Kucheryavskiy, Oxana Rodionova, Alexey Pomerantsev</em></p>
   <p>
      Interactive web-application for creating and using PCA models for data exploration
      directly in your browser. The app does not send any information to the server,
      all calculations are done locally on your device.
   </p>
   <p>Check out YouTube <a href="https://www.youtube.com/playlist?list=PLep7KM9cEyFmpfjgu7n4y-slf8AAN74xC">video-lessons</a></p>
   <h3>v. 2.6.2</h3>
   <p class="release-info">released 01/11/2026</p>
   <ul>
      <li>New higher-contrast theme for the control elements.</li>
      <li>Improved accessibility of the controls.</li>
      <li>Fixed CSV export of PV-set results, where values were shifted relative to the objects.</li>
      <li>Added possibility to save plot data as CSV file.</li>
      <li>New more efficient and faster session system.</li>
      <li>Small bug fixes and improvements.</li>
   </ul>
   {/snippet}
</App>
